def compute(vars):
    restructuring_charges = vars["v1"]
    total_charges = vars["v2"]

    if total_charges == 0:
        return None

    percentage = restructuring_charges / total_charges * 100

    return {
        "value": percentage,
        "trace": {
            "restructuring_charges": restructuring_charges,
            "total_charges": total_charges,
            "ratio": restructuring_charges / total_charges,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
